1	class BrunoRequest {
2	  /**
3	   * The following properties are available as shorthand:
4	   * - req.url
5	   * - req.method
6	   * - req.headers
7	   * - req.timeout
8	   * - req.body
9	   *
10	   * Above shorthands are useful for accessing the request properties directly in the scripts
11	   * It must be noted that the user cannot set these properties directly.
12	   * They should use the respective setter methods to set these properties.
13	   */
14	  constructor(req) {
15	    this.req = req;
16	    this.url = req.url;
17	    this.method = req.method;
18	    this.headers = req.headers;
19	    this.timeout = req.timeout;
20	    this.name = req.name;
21	    this.pathParams = req.pathParams;
22	    this.tags = req.tags || [];
23	    /**
24	     * We automatically parse the JSON body if the content type is JSON
25	     * This is to make it easier for the user to access the body directly
26	     *
27	     * It must be noted that the request data is always a string and is what gets sent over the network
28	     * If the user wants to access the raw data, they can use getBody({raw: true}) method
29	     */
30	    const isJson = this.hasJSONContentType(this.req.headers);
31	    if (isJson) {
32	      this.body = this.__safeParseJSON(req.data);
33	    }
34	  }
35	
36	  getUrl() {
37	    return this.req.url;
38	  }
39	
40	  setUrl(url) {
41	    this.url = url;
42	    this.req.url = url;
43	  }
44	
45	  getHost() {
46	    try {
47	      const url = new URL(this.req.url);
48	      return url.host;
49	    } catch (e) {
50	      return '';
51	    }
52	  }
53	
54	  getPath() {
55	    try {
56	      const url = new URL(this.req.url);
57	      let pathname = url.pathname;
58	
59	      // If path params exist, interpolate them into the pathname
60	      if (this.req.pathParams && Array.isArray(this.req.pathParams)) {
61	        pathname = pathname
62	          .split('/')
63	          .map((segment) => {
64	            if (segment.startsWith(':')) {
65	              const paramName = segment.slice(1);
66	              const pathParam = this.req.pathParams.find((param) => param.name === paramName);
67	              if (pathParam && pathParam.value) {
68	                return pathParam.value;
69	              }
70	            }
71	            return segment;
72	          })
73	          .join('/');
74	      }
75	
76	      return pathname;
77	    } catch (e) {
78	      return '';
79	    }
80	  }
81	
82	  getQueryString() {
83	    try {
84	      const url = new URL(this.req.url);
85	      // Return query string without the leading '?'
86	      return url.search ? url.search.substring(1) : '';
87	    } catch (e) {
88	      return '';
89	    }
90	  }
91	
92	  getMethod() {
93	    return this.req.method;
94	  }
95	
96	  getAuthMode() {
97	    if (this.req?.oauth2) {
98	      return 'oauth2';
99	    } else if (this.req?.oauth1config) {
100	      return 'oauth1';
101	    } else if (this.headers?.['Authorization']?.startsWith('Bearer')) {
102	      return 'bearer';
103	    } else if (this.headers?.['Authorization']?.startsWith('Basic') || this.req?.auth?.username) {
104	      return 'basic';
105	    } else if (this.req?.awsv4) {
106	      return 'awsv4';
107	    } else if (this.req?.digestConfig) {
108	      return 'digest';
109	    } else if (this.headers?.['X-WSSE'] || this.req?.auth?.username) {
110	      return 'wsse';
111	    } else {
112	      return 'none';
113	    }
114	  }
115	
116	  setMethod(method) {
117	    this.method = method;
118	    this.req.method = method;
119	  }
120	
121	  getHeaders() {
122	    return this.req.headers;
123	  }
124	
125	  setHeaders(headers) {
126	    this.headers = headers;
127	    this.req.headers = headers;
128	  }
129	
130	  deleteHeaders(headers) {
131	    headers.forEach((name) => this.deleteHeader(name));
132	  }
133	
134	  getHeader(name) {
135	    return this.req.headers[name];
136	  }
137	
138	  setHeader(name, value) {
139	    this.headers[name] = value;
140	    this.req.headers[name] = value;
141	  }
142	
143	  deleteHeader(name) {
144	    delete this.headers[name];
145	    delete this.req.headers[name];
146	
147	    /**
148	      Store header name to be applied in the axios request interceptor.
149	      Default headers (user-agent, accept, accept-encoding, etc.) are added after
150	      the pre-request script runs, so we track them here and delete them later.
151	    */
152	    if (!this.req.__headersToDelete) {
153	      this.req.__headersToDelete = [];
154	    }
155	    if (!this.req.__headersToDelete.includes(name)) {
156	      this.req.__headersToDelete.push(name);
157	    }
158	  }
159	
160	  hasJSONContentType(headers) {
161	    const contentType = headers?.['Content-Type'] || headers?.['content-type'] || '';
162	    return contentType.includes('json');
163	  }
164	
165	  /**
166	   * Get the body of the request
167	   *
168	   * We automatically parse and return the JSON body if the content type is JSON
169	   * If the user wants the raw body, they can pass the raw option as true
170	   */
171	  getBody(options = {}) {
172	    if (options.raw) {
173	      return this.req.data;
174	    }
175	
176	    const isJson = this.hasJSONContentType(this.req.headers);
177	    if (isJson) {
178	      return this.__safeParseJSON(this.req.data);
179	    }
180	
181	    return this.req.data;
182	  }
183	
184	  /**
185	   * If the content type is JSON and if the data is an object
186	   *  - We set the body property as the object itself
187	   *  - We set the request data as the stringified JSON as it is what gets sent over the network
188	   * Otherwise
189	   *  - We set the request data as the data itself
190	   *  - We set the body property as the data itself
191	   *
192	   * If the user wants to override this behavior, they can pass the raw option as true
193	   */
194	  setBody(data, options = {}) {
195	    if (options.raw) {
196	      this.req.data = data;
197	      this.body = data;
198	      return;
199	    }
200	
201	    const isJson = this.hasJSONContentType(this.req.headers);
202	    if (isJson && this.__isObject(data)) {
203	      this.body = data;
204	      this.req.data = this.__safeStringifyJSON(data);
205	      return;
206	    }
207	
208	    this.req.data = data;
209	    this.body = data;
210	  }
211	
212	  setMaxRedirects(maxRedirects) {
213	    this.req.maxRedirects = maxRedirects;
214	  }
215	
216	  getTimeout() {
217	    return this.req.timeout;
218	  }
219	
220	  setTimeout(timeout) {
221	    this.timeout = timeout;
222	    this.req.timeout = timeout;
223	  }
224	
225	  onFail(callback) {
226	    if (typeof callback === 'function') {
227	      this.req.onFailHandler = callback;
228	    } else if (callback) {
229	      throw new Error(`${callback} is not a function`);
230	    }
231	  }
232	
233	  __safeParseJSON(str) {
234	    try {
235	      return JSON.parse(str);
236	    } catch (e) {
237	      return str;
238	    }
239	  }
240	
241	  __safeStringifyJSON(obj) {
242	    try {
243	      return JSON.stringify(obj);
244	    } catch (e) {
245	      return obj;
246	    }
247	  }
248	
249	  __isObject(obj) {
250	    return obj !== null && typeof obj === 'object';
251	  }
252	
253	  disableParsingResponseJson() {
254	    this.req.__brunoDisableParsingResponseJson = true;
255	  }
256	
257	  getExecutionMode() {
258	    return this.req.__bruno__executionMode;
259	  }
260	
261	  getName() {
262	    return this.req.name;
263	  }
264	
265	  getPathParams() {
266	    const params = Array.isArray(this.req.pathParams) ? this.req.pathParams : [];
267	
268	    return params.map((param) => ({
269	      name: param.name,
270	      value: param.value,
271	      type: param.type
272	    }));
273	  }
274	
275	  /**
276	   * Get the tags associated with this request
277	   * @returns {Array<string>} Array of tag strings
278	   */
279	  getTags() {
280	    return this.req.tags || [];
281	  }
282	}
283	
284	module.exports = BrunoRequest;
