1	const { get } = require('@usebruno/query');
2	const _ = require('lodash');
3	
4	class BrunoResponse {
5	  constructor(res) {
6	    this.res = res;
7	    this.status = res ? res.status : null;
8	    this.statusText = res ? res.statusText : null;
9	    this.headers = res ? res.headers : null;
10	    this.body = res ? res.data : null;
11	    this.responseTime = res ? res.responseTime : null;
12	    this.url = res?.request ? res.request.protocol + '//' + res.request.host + res.request.path : null;
13	
14	    // Make the instance callable
15	    const callable = (...args) => get(this.body, ...args);
16	    Object.setPrototypeOf(callable, this.constructor.prototype);
17	    Object.assign(callable, this);
18	
19	    return callable;
20	  }
21	
22	  getStatus() {
23	    return this.res ? this.res.status : null;
24	  }
25	
26	  getStatusText() {
27	    return this.res ? this.res.statusText : null;
28	  }
29	
30	  getHeader(name) {
31	    return this.res && this.res.headers ? this.res.headers[name] : null;
32	  }
33	
34	  getHeaders() {
35	    return this.res ? this.res.headers : null;
36	  }
37	
38	  getBody() {
39	    return this.res ? this.res.data : null;
40	  }
41	
42	  getResponseTime() {
43	    return this.res ? this.res.responseTime : null;
44	  }
45	
46	  getUrl() {
47	    return this.res ? this.url : null;
48	  }
49	
50	  setBody(data) {
51	    if (!this.res) {
52	      return;
53	    }
54	
55	    const clonedData = _.cloneDeep(data);
56	    this.res.data = clonedData;
57	    this.body = clonedData;
58	
59	    // Update dataBuffer to match the modified body
60	    if (clonedData === null || clonedData === undefined) {
61	      this.res.dataBuffer = Buffer.from('');
62	    } else if (typeof clonedData === 'string') {
63	      this.res.dataBuffer = Buffer.from(clonedData);
64	    } else {
65	      // For objects, stringify them
66	      try {
67	        this.res.dataBuffer = Buffer.from(JSON.stringify(clonedData));
68	      } catch (e) {
69	        this.res.dataBuffer = Buffer.from('');
70	      }
71	    }
72	  }
73	
74	  // TODO: Refactor: dataBuffer size calculation should be handled in a shared utility so it can be passed and reused across the application
75	  getSize() {
76	    if (!this.res) {
77	      return { header: 0, body: 0, total: 0 };
78	    }
79	
80	    const { data, dataBuffer, headers } = this.res;
81	    let bodySize = 0;
82	
83	    // Use raw received bytes
84	    if (Buffer.isBuffer(dataBuffer)) {
85	      bodySize = dataBuffer.length;
86	    } else {
87	      // Use server-reported Content-Length
88	      const contentLength = headers && (headers['content-length'] || headers['Content-Length']);
89	      if (contentLength && !isNaN(contentLength)) {
90	        bodySize = parseInt(contentLength, 10);
91	      } else if (data != null) {
92	        // Manual calculation
93	        const raw = typeof data === 'string' ? data : JSON.stringify(data);
94	        bodySize = Buffer.byteLength(raw);
95	      }
96	    }
97	
98	    const headerLines = [
99	      `HTTP/1.1 ${this.res.status} ${this.res.statusText}`,
100	      ...Object.entries(this.res.headers || {}).flatMap(([key, value]) =>
101	        Array.isArray(value)
102	          ? value.map((v) => `${key}: ${v}`)
103	          : [`${key}: ${value}`]
104	      ),
105	      '',
106	      ''
107	    ];
108	    const headerSize = Buffer.byteLength(headerLines.join('\r\n'));
109	
110	    return { header: headerSize, body: bodySize, total: headerSize + bodySize };
111	  }
112	
113	  getDataBuffer() {
114	    return this.res ? this.res.dataBuffer : null;
115	  }
116	}
117	
118	module.exports = BrunoResponse;
