1	const ReadOnlyPropertyList = require('./readonly-property-list');
2	
3	/**
4	 * PropertyList - A mutable collection data structure.
5	 *
6	 * Extends ReadOnlyPropertyList with mutation methods that operate on the
7	 * internal _items array in static mode. In dynamic mode, all mutations
8	 * throw — subclasses (e.g. CookieList) override with async implementations.
9	 *
10	 * Class hierarchy:
11	 *   ReadOnlyPropertyList  (read-only, both modes)
12	 *     └── PropertyList    (sync mutations in static mode; throws in dynamic mode)
13	 *          └── CookieList (overrides add/upsert/remove/clear/delete with async jar ops)
14	 */
15	class PropertyList extends ReadOnlyPropertyList {
16	  /**
17	   * Guard that throws in dynamic mode. Called by all mutation methods.
18	   * @param {string} method - Name of the calling method (for error message)
19	   */
20	  #ensureStaticMode(method) {
21	    if (this._dynamic) {
22	      throw new Error(`${method}() is not supported in dynamic mode. Override in subclass.`);
23	    }
24	  }
25	
26	  // ── Mutation methods ──────────────────────────────────────────────────
27	
28	  /**
29	   * Append an item to the end of the list.
30	   * @param {object} item
31	   */
32	  add(item) {
33	    this.#ensureStaticMode('add');
34	    this._items.push(item);
35	  }
36	
37	  /**
38	   * Alias for add().
39	   * @param {object} item
40	   */
41	  append(item) {
42	    return this.add(item);
43	  }
44	
45	  /**
46	   * Insert an item at the beginning of the list.
47	   * @param {object} item
48	   */
49	  prepend(item) {
50	    this.#ensureStaticMode('prepend');
51	    this._items.unshift(item);
52	  }
53	
54	  /**
55	   * Insert an item before a reference item.
56	   * @param {object} item - The item to insert
57	   * @param {string|object} before - Key string or item object to insert before
58	   */
59	  insert(item, before) {
60	    this.#ensureStaticMode('insert');
61	    const idx = this.#findIndex(before);
62	    if (idx === -1) {
63	      this._items.push(item);
64	    } else {
65	      this._items.splice(idx, 0, item);
66	    }
67	  }
68	
69	  /**
70	   * Insert an item after a reference item.
71	   * @param {object} item - The item to insert
72	   * @param {string|object} after - Key string or item object to insert after
73	   */
74	  insertAfter(item, after) {
75	    this.#ensureStaticMode('insertAfter');
76	    const idx = this.#findIndex(after);
77	    if (idx === -1) {
78	      this._items.push(item);
79	    } else {
80	      this._items.splice(idx + 1, 0, item);
81	    }
82	  }
83	
84	  /**
85	   * Remove items matching a predicate, key string, or item reference.
86	   * @param {Function|string|object} predicate
87	   */
88	  remove(predicate) {
89	    this.#ensureStaticMode('remove');
90	    if (typeof predicate === 'function') {
91	      this._items = this._items.filter((item) => !predicate(item));
92	    } else if (typeof predicate === 'string') {
93	      this._items = this._items.filter((item) => item[this._keyProperty] !== predicate);
94	    } else if (predicate && typeof predicate === 'object') {
95	      const idx = this.indexOf(predicate);
96	      if (idx !== -1) {
97	        this._items.splice(idx, 1);
98	      }
99	    }
100	  }
101	
102	  /**
103	   * Remove all items from the list.
104	   */
105	  clear() {
106	    this.#ensureStaticMode('clear');
107	    this._items = [];
108	  }
109	
110	  /**
111	   * Update an existing item by key, or append if not found.
112	   * @param {object} item
113	   */
114	  upsert(item) {
115	    this.#ensureStaticMode('upsert');
116	    const key = item[this._keyProperty];
117	    const idx = this._items.findIndex((i) => i[this._keyProperty] === key);
118	    if (idx !== -1) {
119	      this._items[idx] = item;
120	    } else {
121	      this._items.push(item);
122	    }
123	  }
124	
125	  /**
126	   * Replace all items with a new array.
127	   * @param {Array} items
128	   */
129	  populate(items) {
130	    this.#ensureStaticMode('populate');
131	    this._items = Array.isArray(items) ? [...items] : [];
132	  }
133	
134	  /**
135	   * Clear and repopulate with new items.
136	   * @param {Array} items
137	   */
138	  repopulate(items) {
139	    this.#ensureStaticMode('repopulate');
140	    this.populate(items);
141	  }
142	
143	  /**
144	   * Merge items from another PropertyList or array.
145	   * @param {PropertyList|Array} source - Source of items to merge
146	   * @param {boolean} [prune=false] - If true, clear existing items first
147	   */
148	  assimilate(source, prune) {
149	    this.#ensureStaticMode('assimilate');
150	    if (prune) {
151	      this._items = [];
152	    }
153	    let items;
154	    if (ReadOnlyPropertyList.isPropertyList(source)) {
155	      items = source.all();
156	    } else if (Array.isArray(source)) {
157	      items = source;
158	    } else {
159	      items = [];
160	    }
161	    for (const item of items) {
162	      this._items.push(item);
163	    }
164	  }
165	
166	  // ── Internal helpers ──────────────────────────────────────────────────
167	
168	  /**
169	   * Find the index of a reference (key string or item object).
170	   * @param {string|object} ref
171	   * @returns {number}
172	   */
173	  #findIndex(ref) {
174	    if (typeof ref === 'string') {
175	      return this._items.findIndex((i) => i[this._keyProperty] === ref);
176	    }
177	    if (ref && typeof ref === 'object') {
178	      return this.indexOf(ref);
179	    }
180	    return -1;
181	  }
182	}
183	
